:root {
    --bg-primary: #0d1117;
    --bg-secondary: #161b22;
    --bg-tertiary: #1c2128;
    --accent-color: #4fc3f7;
    --accent-hover: #64b5f7;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --border-color: #30363d;
    --radius: 8px;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    min-height: 100vh;
    padding: 20px;
    color: var(--text-secondary);
}
.slide { display: none; }
.slide.active { display: block; }
.slide pre {
    white-space: pre-wrap;
    font-size: 1rem;
    margin: 15px 0;
}
.slide h2 { color: var(--accent-color); margin-bottom: 20px; font-size: 1.4rem; }
.navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 15px;
    background: #1c2128;
    border-radius: var(--radius);
    margin-bottom: 20px;
    border: 1px solid #30363d;
}
.navbar h1 { color: var(--accent-color); font-size: 1.4rem; }
.nav-links a {
    display: inline-block;
    padding: 8px 16px;
    margin: 0 5px;
    background: var(--accent-color);
    color: white;
    text-decoration: none;
    border-radius: 5px;
    font-size: 0.9rem;
}
.nav-controls { display: flex; justify-content: center; gap: 10px; }
.btn {
    padding: 10px 20px;
    background: #30363d;
    color: var(--accent-color);
    border: 1px solid #30363d;
    border-radius: 5px;
    cursor: pointer;
}
.btn:hover { background: #3f4958; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.toc {
    margin: 30px auto;
    padding: 25px;
    background: #1c2128;
    border-radius: var(--radius);
    width: 100%;
}
.toc h3 { color: var(--accent-color); margin-bottom: 15px; }
.toc ul { list-style: none; display: flex; flex-direction: column; gap: 6px; }
.toc li {
    padding: 6px 10px;
    background: #1c2128;
    border-radius: 4px;
    color: var(--text-secondary);
    cursor: pointer;
}
.toc li:hover { color: var(--accent-color); }
@media (max-width: 768px) {
    .navbar, .slide { padding: 15px; }
    .nav-links a { padding: 6px 12px; font-size: 0.85rem; }
}

let slides = document.querySelectorAll('.slide');
let currentIndex = 0;

function showSlide(index) {
    if (index < 0 || index >= slides.length) return;
    slides.forEach((slide, i) => slide.classList.toggle('active', i === index));
    document.querySelector('.nav-links a.active')?.classList.remove('active');
    if (index === 0) document.querySelector('.nav-links a.active')?.classList.add('active');
    return index;
}

function nextSlide() { showSlide(currentIndex + 1); }
function prevSlide() { showSlide(currentIndex - 1); }
document.querySelector('.btn-next')?.addEventListener('click', nextSlide);
document.querySelector('.btn-prev')?.addEventListener('click', prevSlide);
document.querySelector('.btn-top')?.addEventListener('click', () => { showSlide(0); window.scrollTo({top: 0, behavior: 'smooth'}); });

slides.forEach(slide => {
    slide.addEventListener('click', (e) => {
        if (e.target.tagName === 'A') {
            e.preventDefault();
            const href = e.target.getAttribute('href').replace('#', '').replace('/#', '');
            const idx = Array.from(slides).findIndex(s => s.id === href);
            if (idx !== -1) showSlide(idx);
        }
    });
});

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') nextSlide();
    if (e.key === 'ArrowLeft') prevSlide();
    if (e.key === 'Home') showSlide(0);
    if (e.key === 'End') showSlide(slides.length - 1);
});

