:root {
    --bg-primary: #0d1117;
    --bg-secondary: #161b22;
    --bg-tertiary: #1c2128;
    --bg-panel: #12161c;
    --accent-color: #4fc3f7;
    --accent-hover: #64b5f7;
    --accent-text: #0288d1;
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-muted: #6e7681;
    --border-color: #30363d;
    --border-light: #21262d;
    --radius: 8px;
    --radius-small: 4px;
    --shadow: 0 4px 12px rgba(0, 0, 0, 0.3);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    background: linear-gradient(135deg, var(--bg-primary), var(--bg-secondary));
    color: var(--text-primary);
    overflow: hidden;
}
.presentation {
    display: flex;
    height: 100vh;
    overflow: hidden;
}
/* Side panel - always visible on desktop, toggleable */
.side-panel {
    width: 280px;
    min-width: 240px;
    max-width: 70vw;
    background: var(--bg-panel);
    border-right: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    transition: transform 0.3s ease, opacity 0.3s ease;
}
.side-panel.hidden {
    transform: translateX(-100%);
    opacity: 0;
}
@media (max-width: 768px) {
    .side-panel {
        display: none;
        opacity: 0;
        transform: translateX(-100%);
    }
}
/* Side panel header */
.side-panel-header {
    padding: 16px;
    border-bottom: 1px solid var(--border-color);
}
.side-panel-header h2 {
    color: var(--accent-color);
    font-size: 1.1rem;
    font-weight: 600;
}
.side-panel-divider {
    border: none;
    border-top: 1px solid var(--border-light);
    margin: 12px 0;
}
/* Side panel content */
.side-panel-content {
    padding: 16px;
    overflow-y: auto;
    flex: 1;
}
/* Table of contents in side panel */
.side-panel-toc {
    list-style: none;
}
.side-panel-toc li {
    margin-bottom: 8px;
}
.side-panel-toc a {
    display: block;
    padding: 10px 12px;
    color: var(--text-secondary);
    text-decoration: none;
    border-radius: var(--radius-small);
    transition: background 0.2s, color 0.2s;
    font-size: 0.9rem;
}
.side-panel-toc a:hover {
    background: var(--bg-tertiary);
    color: var(--text-primary);
}
.side-panel-toc a.active {
    background: var(--bg-tertiary);
    color: var(--accent-color);
    border-left: 3px solid var(--accent-color);
}
.side-panel-toc a:hover,
.side-panel-toc a.active {
    color: var(--accent-color);
}
.side-panel-toc .arrow-right {
    display: inline-block;
    margin-left: 6px;
    opacity: 0.6;
}
/* Hidden TOC panel */
.side-panel-toc-hidden {
    flex: 1;
}
/* Main content area */
.main-content {
    flex: 1;
    overflow-y: auto;
    position: relative;
}
.slide {
    height: 100%;
    padding: 100px 80px 60px;
    display: none;
    border-bottom: 1px solid transparent;
}
.slide.active {
    display: block;
}
.slide h2 {
    color: var(--accent-text);
    font-size: 2.2rem;
    font-weight: 600;
    margin-bottom: 30px;
    letter-spacing: -0.5px;
}
.slide-content {
    max-width: 800px;
    margin: 0 auto;
    padding: 40px 20px;
    background: var(--bg-tertiary);
    border-radius: var(--radius);
    border: 1px solid var(--border-color);
    box-shadow: var(--shadow);
}
.slide-content pre {
    white-space: pre-wrap;
    font-size: 1.05rem;
    line-height: 1.6;
    color: var(--text-primary);
    overflow-y: auto;
    max-height: 500px;
    margin: 0;
    font-family: 'SF Mono', Monaco, 'Cascadia Code', Andale Mono, monospace;
    padding: 20px;
}
.slide-footer {
    max-width: 800px;
    margin: 20px auto 0;
    padding: 15px;
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
}
/* Slide links/buttons */
.link-btn {
    display: inline-flex;
    align-items: center;
    padding: 8px 14px;
    background: var(--bg-tertiary);
    color: var(--accent-text);
    text-decoration: none;
    border-radius: var(--radius-small);
    font-size: 0.9rem;
    border: 1px solid var(--border-color);
    transition: background 0.2s, transform 0.1s;
}
.link-btn:hover {
    background: var(--bg-secondary);
    transform: translateY(-1px);
}
.link-btn:active {
    transform: translateY(0);
}
/* Footer */
.footer {
    position: fixed;
    bottom: 0;
    left: 280px;
    right: 0;
    height: 56px;
    background: var(--bg-tertiary);
    border-top: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    z-index: 100;
}
@media (max-width: 768px) {
    .footer {
        left: 0;
        flex-direction: column;
        height: 60px;
        gap: 6px;
    }
    .footer button {
        min-width: 80px !important;
    }
}
/* Buttons */
.btn {
    padding: 10px 20px;
    min-width: 100px;
    background: var(--bg-secondary);
    color: var(--text-primary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius);
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.2s, color 0.2s;
}
.btn:hover {
    background: var(--bg-tertiary);
    border-color: var(--accent-color);
}
.btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
.btn-toc-toggle {
    width: 36px;
    height: 36px;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
}
.btn-toc-toggle:hover {
    background: var(--bg-secondary);
}
.btn-nav {
    flex: 1;
}
.btn-prev, .btn-next {
    width: calc(50% - 5px);
    max-width: 180px;
}
.btn-top {
    width: 100px;
}
.btn-close {
    width: 90px;
}
/* Scrollbar styling */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}
::-webkit-scrollbar-track {
    background: var(--bg-secondary);
}
::-webkit-scrollbar-thumb {
    background: var(--border-color);
    border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--text-muted);
}

let slides = document.querySelectorAll('.slide');
let currentIndex = 0;
let totalSlides = slides.length;
let sidePanelHidden = false;

// Initialize
init();

function init() {
    // Set initial TOC item as active
    if (totalSlides > 0) {
        setActiveSlide(0);
    }
}

function setActiveSlide(index) {
    index = Math.max(0, Math.min(index, totalSlides - 1));

    // Show/hide slides
    slides.forEach((slide, i) => {
        if (i === index) {
            slide.classList.add('active');
            // Update TOC active state
            updateSidePanelActive(index);
        } else {
            slide.classList.remove('active');
        }
    });

    currentIndex = index;
}

function updateSidePanelActive(activeIndex) {
    const tocItems = document.querySelectorAll('.side-panel-toc a');
    tocItems.forEach((item, index) => {
        if (index === activeIndex) {
            item.classList.add('active');
        } else {
            item.classList.remove('active');
        }
    });
}

function showSlide(index) {
    if (index < 0 || index >= activeSlideCount()) return;

    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    setActiveSlide(index);

    // Also update nav buttons disable states
    updateNavButtons();
}

function activeSlideCount() {
    return slides.length;
}

function updateNavButtons() {
    const btnPrev = document.getElementById('btn-prev');
    const btnNext = document.getElementById('btn-next');
    const btnTop = document.getElementById('btn-top');

    if (btnPrev) btnPrev.disabled = currentIndex === 0;

    if (btnNext && totalSlides > 1) {
        btnNext.disabled = currentIndex === totalSlides - 1;
    }

    // Enable all buttons for current slide
    if (btnTop) btnTop.disabled = false;
    if (btnNext) btnNext.disabled = true;
    if (btnPrev) btnPrev.disabled = true;
}

function toggleSidePanel() {
    const sidePanel = document.getElementById('side-panel');
    const hiddenPanel = document.getElementById('side-panel-toc-hidden');

    if (sidePanelHidden) {
        sidePanel.classList.remove('hidden');
        hiddenPanel.style.display = 'none';
        hiddenPanel.style.display = 'block';
    } else {
        sidePanel.classList.add('hidden');
        hiddenPanel.style.display = 'none';
        hiddenPanel.style.display = 'block';
    }

    sidePanelHidden = !sidePanelHidden;
}

// Initial check: show TOC by default on desktop
if (window.innerWidth > 768) {
    toggleSidePanel();
}

// Keyboard navigation
document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowRight':
        case ' ':// Space to next
            if (showSlide(currentIndex + 1));
            break;
            case 'ArrowLeft':
            case 'e key === 'ArrowLeft':
            case 'b'
        case 'Home':
            showSlide(0);
            break;
        case 'End':
            showSlide(totalSlides - 1);
            break;
        case 't'
        case 'Toggle TOC':
            toggleSidePanel();
            break;
        case 'Escape':
            closeCurrentSlide();
            break;
    }
});

// Close current slide (hide all)
function closeCurrentSlide() {
    slides.forEach(slide => slide.classList.remove('active'));
}

// Click event on slide links
slides.forEach(slide => {
    slide.addEventListener('click', (e) => {
        if (e.target.tagName === 'A' && e.target.classList.contains('link-btn')) {
            const href = e.target.getAttribute('href');
            const id = href.replace('#', '').replace('/#', '');
            const idx = Array.from(slides).findIndex(s => s.id === id);
            if (idx !== -1) {
                e.preventDefault();
                showSlide(idx);
            }
        }
    });
});

// Window resize handler - restore TOC on desktop
let resizeTimer;
window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
        if (sidePanelHidden && window.innerWidth > 768) {
            toggleSidePanel();
        }
    }, 100);
});

// Nav buttons
document.getElementById('btn-prev')?.addEventListener('click', () => showSlide(currentIndex - 1));
document.getElementById('btn-next')?.addEventListener('click', () => showSlide(currentIndex + 1));
document.getElementById('btn-top')?.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
});
document.getElementById('btn-close')?.addEventListener('click', closeCurrentSlide);

// Close buttons from TOC panel
document.addEventListener('click', (e) => {
    if (e.target.classList.contains('btn-close')) {
        closeCurrentSlide();
    }
});

let slides = document.querySelectorAll('.slide');
let currentIndex = 0;
let totalSlides = slides.length;
let sidePanelHidden = false;

// Initialize
init();

function init() {
    if (totalSlides > 0) {
        setActiveSlide(0);
    }
}

function setActiveSlide(index) {
    index = Math.max(0, Math.min(index, totalSlides - 1));

    slides.forEach((slide, i) => {
        if (i === index) {
            slide.classList.add('active');
            updateSidePanelActive(index);
        } else {
            slide.classList.remove('active');
        }
    });

    currentIndex = index;
}

