document.getElementById('btn-next')?.addEventListener('click', () => showSlide(currentIndex + 1));
document.getElementById('btn-top')?.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
document.getElementById('btn-close')?.addEventListener('click', closeCurrentSlide);

